create extension if not exists pgcrypto;
create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),name text not null default 'My workspace',owner_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.workspace_members(workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','admin','member','viewer')),created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,description text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,project_id uuid references public.projects(id) on delete set null,title text not null,description text,status text not null default 'todo' check(status in('backlog','todo','progress','review','done')),priority text not null default 'medium' check(priority in('low','medium','high')),due_date date,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.is_workspace_member(wid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members where workspace_id=wid and user_id=auth.uid()); $$;
alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.projects enable row level security;alter table public.tasks enable row level security;
create policy "workspace members read workspaces" on public.workspaces for select using(public.is_workspace_member(id));
create policy "users create own workspace" on public.workspaces for insert with check(owner_id=auth.uid());
create policy "owners update workspace" on public.workspaces for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "members read membership" on public.workspace_members for select using(user_id=auth.uid() or public.is_workspace_member(workspace_id));
create policy "owners add members" on public.workspace_members for insert with check(exists(select 1 from public.workspaces w where w.id=workspace_id and w.owner_id=auth.uid()));
create policy "members read projects" on public.projects for select using(public.is_workspace_member(workspace_id));
create policy "members create projects" on public.projects for insert with check(public.is_workspace_member(workspace_id) and created_by=auth.uid());
create policy "members update projects" on public.projects for update using(public.is_workspace_member(workspace_id));
create policy "members delete projects" on public.projects for delete using(public.is_workspace_member(workspace_id));
create policy "members read tasks" on public.tasks for select using(public.is_workspace_member(workspace_id));
create policy "members create tasks" on public.tasks for insert with check(public.is_workspace_member(workspace_id) and created_by=auth.uid());
create policy "members update tasks" on public.tasks for update using(public.is_workspace_member(workspace_id));
create policy "members delete tasks" on public.tasks for delete using(public.is_workspace_member(workspace_id));
create or replace function public.handle_new_flowboard_user() returns trigger language plpgsql security definer set search_path=public as $$ declare wid uuid; begin insert into public.workspaces(name,owner_id) values('My workspace',new.id) returning id into wid; insert into public.workspace_members(workspace_id,user_id,role) values(wid,new.id,'owner'); return new; end; $$;
drop trigger if exists flowboard_user_created on auth.users;
create trigger flowboard_user_created after insert on auth.users for each row execute procedure public.handle_new_flowboard_user();
